import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"56、【旅】 艮下離上","description":"周易口訣義 - 56、【旅】 艮下離上","frontmatter":{"title":"56、【旅】 艮下離上","description":"周易口訣義 - 56、【旅】 艮下離上"},"headers":[],"relativePath":"classics/koujueyi/058.md","filePath":"classics/koujueyi/058.md"}'),r={name:"classics/koujueyi/058.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_56、【旅】-艮下離上" tabindex="-1">56、【旅】 艮下離上 <a class="header-anchor" href="#_56、【旅】-艮下離上" aria-label="Permalink to “56、【旅】 艮下離上”">​</a></h1><p>彖曰：「旅小亨」，柔得中乎外而順乎剛，止而麗乎明，是以「小亨，旅貞吉」也。旅之時義大矣哉！</p><p>象曰：山上有火，旅。君子以明慎用刑而不留獄。</p><p>初六：旅瑣瑣，斯其所取災。</p><p>象曰：「旅瑣瑣」，志窮災也。</p><p>六二：旅即次，懷其資，得童僕貞。</p><p>象曰：「得童僕貞」，終無尤也。</p><p>九三：旅焚其次，喪其童僕，貞厲。</p><p>象曰：「旅焚其次」，亦以傷矣。以旅與下，其義喪也。</p><p>九四：旅於處，得其資斧，我心不快。</p><p>象曰：「旅於處」，未得位也；「得其資斧」，心未快也。</p><p>六五，射雉，一矢亡，終以譽命。</p><p>象曰：「終以譽命」，上逮也。</p><p>上九，鳥焚其巢，旅人先笑後號啕，喪牛於易，兇。</p><p>象曰：以旅在上，其義焚也，「喪牛於易」，終莫之聞也。</p><p>解讀</p><p>「旅小亨，旅貞吉」者，旅者，客羈旅之稱也。旅人觸目乖阻，困於途路，求容僅存，假道濟通，所通非大，但「小亨」而已，故「旅小亨」也。羈旅而得小通，是旅之正吉，故「旅貞吉」也。象曰「山上有火，旅」者，火在山上，因風而起，逐草而行，勢不久留之象也。「君子以明慎用刑而不留獄」者，旅卦而引斷獄。案六十四卦有文明者多稱用刑，今旅卦有艮止離明，止即審慎用刑，明即不濫不枉，故聖人之意，取其明察止審，不妄刑罰。蓋以人命至重，故陽膚為士師，曾子誡之曰「治獄之道，如得其情，則哀矜而勿喜，死者不可復生，斷者不可復續」是也。</p><p>「初六曰：旅瑣瑣，斯其所取災」者，瑣瑣，細小卑賤之貌也。處旅之時，最居人下，是卑賤細小矣，故「旅瑣瑣」也。身處人下，不得所安，有所興為，災禍自至，故曰「斯其所取災」。</p><p>「六二，旅即次，懷其資，得童僕貞」者，次是旅店，旅人所居之處也。六二以柔居中，得位乘上，即是旅人得其所安，只可店舍而處，故曰「旅即次」也。處旅行謙，不為剛猛，但有童僕之正，懷來資貨，不慮喪失，故曰「懷其資，得童僕貞」也。</p><p>「九三，旅焚其次，喪其童僕，貞厲」者，九三處下卦之上，上無應，與初二相得，遂欲自尊而施惠於下。當旅之時，不能謙和靜慎，而乃預萌侵權，為君所疑，遂被黜奪，焚其次舍，是喪童僕之正而身危矣，故曰「喪其童僕，貞厲」。</p><p>「九四，旅於處，得其資斧，我心不快」者，九四以陽居陰，即懷謙之道。處旅行謙，雖不得平坦之處，而得用斧之地，謂除荊棘而治次舍，以自居之，故曰「旅於處，得其資斧」也。寄旅求安，不得平坦而得荊棘之地，即其心不樂，故曰「我心不快」也。</p><p>「六五：射雉，一矢亡，終以譽命」者，羈旅之時，不可以處盛位，縱使居之，終不可保有，喻射雉一矢，射之不中而失其矢，雉雖有而終不可得，故曰「射雉一矢亡」也。然五居文明之中，能審禍福之機，不乘剛而專權，但棄下而恭願奉上，故終美譽而見命也。</p><p>上九：鳥焚其巢，旅人先笑而後號啕。「喪牛於易，兇」者，居高危以為宅，鳥巢之象。旅人最處高位，眾心所嫉，居嫉害之地，因被侵奪，必致兇塞。得高位而先笑也，兇禍至而後號啕也。侵奪而似鳥焚巢，牛是稼穡之資，喪失其牛，理在不難，眾所同嫉，物莫之與，危而弗扶，無人以為聞報，無所依託，即傷切甚矣，故於易兇。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
